import { Group, PlaneGeometry, Mesh, MeshBasicNodeMaterial, DoubleSide, Box3 } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();
  const cleanupList = [];

  // ── Plane (background) ──────────────────────────────────────────────
  const texture = ctx.textureLoader.load(config.imageUrl);

  // Determine plane dimensions from texture aspect ratio (fallback 1.6)
  let aspect = 1.6;
  if (texture.image) {
    aspect = texture.image.width / texture.image.height;
  }
  const planeWidth = 4;
  const planeHeight = planeWidth / aspect;

  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    map: texture,
    side: DoubleSide,
    transparent: true,
    // Prevent colour cast (texture is the only colour source)
    color: 0xffffff,
  });

  // If the provided atlas region is a sub‑rect, adjust offset/repeat
  // Here the source rect equals the full texture (0,0 → 512,320)
  texture.offset.set(0, 0);
  texture.repeat.set(1, 1);

  const planeMesh = new Mesh(geometry, material);
  group.add(planeMesh);

  cleanupList.push(() => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  });

  // ── Text overlay ────────────────────────────────────────────────────
  const text = config.textContent;
  if (text && text.length > 0) {
    // Build text appearance from design tokens
    const textOptions = {
      text,
      fontSize: 0.13,              // body scale: 0.13 scene units
      fontFamily: 'JetBrains Mono',
      fontWeight: 400,
      color: '#e8ecf2',           // paper – good contrast on dark background
      align: 'center',
      anchorX: 'center',          // horizontal centre
      anchorY: 'middle',          // vertical centre
    };

    const textMesh = ctx.fontAtlas.createText(textOptions);
    // Offset slightly in front of the plane
    textMesh.position.z = 0.01;

    // Centre the text on the plane by accounting for its bounding box
    const box = new Box3().setFromObject(textMesh);
    const textWidth = box.max.x - box.min.x;
    const textHeight = box.max.y - box.min.y;
    textMesh.position.x = -textWidth / 2;
    textMesh.position.y = -textHeight / 2;

    group.add(textMesh);

    cleanupList.push(() => {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    });
  }

  // ── Scene placement from spec ───────────────────────────────────────
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);
  // If config carries dynamic placement, use it instead:
  // if (config.scenePosition) group.position.copy(config.scenePosition);
  // if (config.sceneRotation) group.rotation.set(...config.sceneRotation);
  // if (config.sceneScale) group.scale.set(...config.sceneScale);

  // ── Cinematic primitives (none specified) ───────────────────────────
  // No primitives to apply.

  // ── Event handlers (none) ───────────────────────────────────────────
  group.userData.handlers = {};

  // ── Cleanup ─────────────────────────────────────────────────────────
  group.userData.cleanup = () => {
    cleanupList.forEach(fn => fn());
    // Kill any GSAP timelines (none started)
  };

  return group;
}
